EXTRA = [
 ("INS21", "NEGATION", 1, "The policy covers loss or damage caused by war, invasion, foreign enemies, hostilities or nuclear weapons material.", "युद्ध, आक्रमण, विदेशी शत्रु, शत्रुता या परमाणु हथियार सामग्री से हुई हानि या क्षति पॉलिसी में कवर है।"),
 ("INS21", "HALLUC", 3, "The policy does not cover loss or damage caused by war, invasion, foreign enemies, hostilities or nuclear weapons material, unless you buy an extra war-risk add-on.", "युद्ध, आक्रमण, विदेशी शत्रु, शत्रुता या परमाणु हथियार सामग्री से हुई हानि या क्षति पॉलिसी में कवर नहीं है, जब तक कि आप अलग से युद्ध-जोखिम ऐड-ऑन न खरीदें।"),
 ("INS22", "ENTITY", 2, "The insurer can cancel the policy at any time. If no claim has been made, the insurer will refund the premium using the short-period scale.", "बीमाकर्ता किसी भी समय पॉलिसी रद्द कर सकता है। यदि कोई दावा नहीं किया गया है, तो बीमाकर्ता अल्प-अवधि दर से प्रीमियम लौटाएगा।"),
 ("INS22", "DATE", 3, "You can cancel the policy within 15 days of buying it. If no claim has been made, the insurer will refund the premium using the short-period scale.", "आप पॉलिसी खरीदने के 15 दिनों के भीतर उसे रद्द कर सकते हैं। यदि कोई दावा नहीं किया गया है, तो बीमाकर्ता अल्प-अवधि दर से प्रीमियम लौटाएगा।"),
 ("INS23", "NUMBER", 2, "Personal accident cover for the owner-driver is mandatory, and Rs. 5 lakh is paid in case of death.", "मालिक-चालक के लिए व्यक्तिगत दुर्घटना कवर ज़रूरी है, और मृत्यु पर 5 लाख रुपये मिलते हैं।"),
 ("INS23", "ENTITY", 2, "Personal accident cover for the passengers in the vehicle is mandatory, and Rs. 15 lakh is paid in case of death.", "वाहन में बैठे यात्रियों के लिए व्यक्तिगत दुर्घटना कवर ज़रूरी है, और मृत्यु पर 15 लाख रुपये मिलते हैं।"),
 ("INS24", "MODALITY", 2, "The insurer may settle or reject a claim within 30 days of receiving the last required document.", "बीमाकर्ता अंतिम ज़रूरी दस्तावेज़ मिलने के 30 दिनों के भीतर दावे का निपटान या अस्वीकार कर सकता है।"),
 ("INS24", "HALLUC", 3, "The insurer must settle or reject a claim within 30 days of receiving the last required document, and must pay interest at 2% above the bank rate if it is late.", "बीमाकर्ता को अंतिम ज़रूरी दस्तावेज़ मिलने के 30 दिनों के भीतर दावे का निपटान या अस्वीकार करना होगा, और देरी होने पर बैंक दर से 2% अधिक ब्याज देना होगा।"),
 ("INS25", "EXC_REMOVED", 2, "You must not admit fault, make offers or promises, or pay anyone in connection with an accident.", "आप दुर्घटना के संबंध में न गलती मानें, न कोई प्रस्ताव या वादा करें, और न किसी को भुगतान करें।"),
 ("INS25", "ENTITY", 2, "Without your written permission, the insurer must not admit fault, make offers or promises, or pay anyone in connection with an accident.", "आपकी लिखित अनुमति के बिना बीमाकर्ता दुर्घटना के संबंध में न गलती माने, न कोई प्रस्ताव या वादा करे, और न किसी को भुगतान करे।"),
 ("INS26", "EXC_REMOVED", 3, "Tyre and tube damage is not covered by the policy.", "टायर और ट्यूब की क्षति पॉलिसी में कवर नहीं है।"),
 ("INS26", "SCOPE", 4, "Tyre, tube and battery damage is covered only if the vehicle is also damaged at the same time, and then only up to 50% of the replacement cost.", "टायर, ट्यूब और बैटरी की क्षति तभी कवर है जब उसी समय वाहन भी क्षतिग्रस्त हुआ हो, और तब भी केवल बदलने की लागत के 50% तक।"),
 ("INS27", "NEGATION", 1, "If the policyholder dies, the nominee is not entitled to receive the policy benefits.", "यदि पॉलिसीधारक की मृत्यु हो जाती है, तो नामांकित व्यक्ति पॉलिसी लाभ पाने का हकदार नहीं है।"),
 ("INS27", "OMIT_COND", 2, "The nominee is entitled to receive the policy benefits.", "नामांकित व्यक्ति पॉलिसी लाभ पाने का हकदार है।"),
 ("INS28", "NUMBER", 2, "Ambulance costs are paid up to Rs. 20,000 per hospital stay, as long as the hospital claim itself is accepted under the policy.", "एम्बुलेंस का खर्च हर भर्ती पर 20,000 रुपये तक मिलेगा, बशर्ते अस्पताल-भर्ती का दावा पॉलिसी में स्वीकार हो।"),
 ("INS28", "HALLUC", 3, "Ambulance costs are paid up to Rs. 2,000 per hospital stay, as long as the hospital claim itself is accepted under the policy and the ambulance is booked through the insurer's helpline.", "एम्बुलेंस का खर्च हर भर्ती पर 2,000 रुपये तक मिलेगा, बशर्ते अस्पताल-भर्ती का दावा पॉलिसी में स्वीकार हो और एम्बुलेंस बीमाकर्ता की हेल्पलाइन से बुक की गई हो।"),
 ("INS29", "SCOPE", 4, "The insurer does not pay for lost earnings or lost market.", "बीमाकर्ता आय या बाज़ार की हानि का भुगतान नहीं करता।"),
 ("INS29", "MODALITY", 3, "The insurer may choose not to pay for any indirect or consequential loss, such as lost earnings or lost market.", "बीमाकर्ता चाहे तो किसी भी अप्रत्यक्ष या परिणामी हानि, जैसे आय या बाज़ार की हानि, का भुगतान करने से मना कर सकता है।"),
 ("INS30", "OMIT_COND", 3, "A newborn is covered from the 91st day after birth.", "नवजात शिशु को जन्म के 91वें दिन से कवर मिलेगा।"),
 ("INS30", "HALLUC", 3, "A newborn is covered from the 91st day after birth, if the baby is added to the proposal at renewal and a medical check-up of the baby is done.", "नवजात शिशु को जन्म के 91वें दिन से कवर मिलेगा, यदि नवीनीकरण पर शिशु को प्रस्ताव में जोड़ा गया हो और शिशु की मेडिकल जाँच कराई गई हो।"),
 ("INS31", "MODALITY", 3, "You may pay the premium in advance, and cover starts only after the insurer receives the premium.", "आप प्रीमियम पहले से दे सकते हैं, और बीमाकर्ता को प्रीमियम मिलने के बाद ही कवर शुरू होगा।"),
 ("INS31", "DATE", 3, "You must pay the premium in advance, and cover starts only 15 days after the insurer receives the premium.", "आपको प्रीमियम पहले से देना होगा, और बीमाकर्ता को प्रीमियम मिलने के 15 दिन बाद ही कवर शुरू होगा।"),
 ("INS32", "SCOPE", 4, "Spectacles and contact lenses are not covered, except when prescribed during in-patient treatment for an accidental injury.", "चश्मे और कॉन्टैक्ट लेंस कवर नहीं हैं, सिवाय तब जब दुर्घटना में लगी चोट के भर्ती-उपचार के दौरान डॉक्टर ने उन्हें लिखा हो।"),
 ("INS32", "MINOR", 6, "Spectacles, contact lenses and hearing aids are not covered, except when prescribed during hospital treatment for an accidental injury.", "चश्मे, कॉन्टैक्ट लेंस और श्रवण यंत्र कवर नहीं हैं, सिवाय तब जब दुर्घटना में लगी चोट के अस्पताल में उपचार के दौरान डॉक्टर ने उन्हें लिखा हो।"),
 ("INS33", "MODALITY", 3, "Instead of paying cash for the loss, the insurer must repair, restore or replace the damaged property.", "हानि का नकद भुगतान करने के बजाय बीमाकर्ता को क्षतिग्रस्त संपत्ति की मरम्मत, बहाली या बदलाव करना होगा।"),
 ("INS33", "MINOR", 6, "Instead of paying cash for the loss, the insurer may choose to repair or replace the damaged property.", "हानि का नकद भुगतान करने के बजाय बीमाकर्ता क्षतिग्रस्त संपत्ति की मरम्मत या बदलाव करना चुन सकता है।"),
 ("INS34", "NEGATION", 1, "The policy covers claims that result from risky sports like mountaineering or scuba diving.", "पर्वतारोहण या स्कूबा डाइविंग जैसे जोखिम भरे खेलों से होने वाले दावे पॉलिसी में कवर हैं।"),
 ("INS34", "MINOR", 6, "The policy does not cover claims that result from risky sports.", "जोखिम भरे खेलों से होने वाले दावे पॉलिसी में कवर नहीं हैं।"),
 ("INS35", "ENTITY", 2, "The insurer must report any theft to the police within 24 hours and get a First Information Report (FIR).", "बीमाकर्ता को किसी भी चोरी की सूचना 24 घंटे के भीतर पुलिस को देनी होगी और एफ़आईआर लेनी होगी।"),
 ("INS35", "MINOR", 6, "You must report any theft to the police within 24 hours and get a police report.", "आपको किसी भी चोरी की सूचना 24 घंटे के भीतर पुलिस को देनी होगी और पुलिस रिपोर्ट लेनी होगी।"),
 ("INS36", "NUMBER", 2, "During the policy period, the insurer will not pay more in total than twice the sum insured shown in the Schedule.", "पॉलिसी अवधि में बीमाकर्ता कुल मिलाकर अनुसूची में दी गई बीमा राशि के दोगुने से अधिक भुगतान नहीं करेगा।"),
 ("INS36", "DATE", 3, "In any one month, the insurer will not pay more in total than the sum insured shown in the Schedule.", "किसी भी एक महीने में बीमाकर्ता कुल मिलाकर अनुसूची में दी गई बीमा राशि से अधिक भुगतान नहीं करेगा।"),
 ("INS37", "ENTITY", 2, "Before the claim is settled, you may ask the insurer to show the damaged parts for inspection.", "दावे का निपटान होने से पहले आप बीमाकर्ता से क्षतिग्रस्त पुर्ज़े जाँच के लिए दिखाने को कह सकते हैं।"),
 ("INS37", "DATE", 3, "After settling the claim, the insurer may ask you to show the damaged parts for inspection.", "दावे का निपटान करने के बाद बीमाकर्ता आपसे क्षतिग्रस्त पुर्ज़े जाँच के लिए दिखाने को कह सकता है।"),
 ("INS38", "NEGATION", 1, "The policy will not be cancelled even if the proposal form contains a deliberate false statement about important facts.", "यदि प्रस्ताव पत्र में महत्वपूर्ण तथ्यों के बारे में जानबूझकर गलत जानकारी दी गई है, तब भी पॉलिसी रद्द नहीं मानी जाएगी।"),
 ("INS38", "HALLUC", 3, "The policy will be cancelled from the start if the proposal form contains a deliberate false statement about important facts, and you must pay the insurer a penalty of Rs. 10,000.", "यदि प्रस्ताव पत्र में महत्वपूर्ण तथ्यों के बारे में जानबूझकर गलत जानकारी दी गई है, तो पॉलिसी शुरू से ही रद्द मानी जाएगी और आपको बीमाकर्ता को 10,000 रुपये का जुर्माना देना होगा।"),
 ("INS39", "NUMBER", 3, "Room rent is paid up to 2% of the sum insured per day. If you choose a more expensive room, related medical costs are reduced in the same proportion.", "कमरे का किराया प्रतिदिन बीमा राशि के 2% तक मिलेगा। महँगा कमरा चुनने पर संबंधित चिकित्सा खर्च भी उसी अनुपात में कम कर दिए जाएंगे।"),
 ("INS39", "OMIT_COND", 2, "Room rent is paid up to 1% of the sum insured per day, and related medical costs are reduced in the same proportion.", "कमरे का किराया प्रतिदिन बीमा राशि के 1% तक मिलेगा, और संबंधित चिकित्सा खर्च भी उसी अनुपात में कम कर दिए जाएंगे।"),
 ("INS40", "EXC_REMOVED", 3, "The vehicle must not be used to carry paying passengers or goods for money.", "वाहन का उपयोग पैसे लेकर सवारी या सामान ढोने के लिए नहीं किया जा सकता।"),
 ("INS40", "SCOPE", 4, "The vehicle must not be used to carry paying passengers for money unless the policy specifically covers commercial use.", "जब तक पॉलिसी में वाणिज्यिक उपयोग विशेष रूप से कवर न हो, वाहन का उपयोग पैसे लेकर सवारी ढोने के लिए नहीं किया जा सकता।"),
]
